from rdkit import Chem
from rdkit.Chem import AllChem
# 2D from drawing, y flipped
pts={'Cq':(290,-170),'Ct':(365,-70),'Ca':(480,-105),'Cm':(575,-35),'O':(650,-120),'Cb':(480,-225),'Cr':(580,-295),'Me1':(690,-265),'Me2':(578,-410),'Cbot':(365,-262),'E1':(230,-110),'E2':(230,-230)}
rw=Chem.RWMol()
idx={}
for k in pts:
    sym='O' if k=='O' else 'C'
    idx[k]=rw.AddAtom(Chem.Atom(sym))
bonds=[('Cq','Ct'),('Ct','Ca'),('Ca','Cm'),('Cm','O'),('Ca','Cb'),('Cb','Cr'),('Cr','Me1'),('Cr','Me2'),('Cb','Cbot'),('Cbot','Cq'),('Cq','E1'),('Cq','E2')]
for a,b in bonds: rw.AddBond(idx[a],idx[b],Chem.BondType.SINGLE)
conf=Chem.Conformer(len(pts))
for k,(x,y) in pts.items(): conf.SetAtomPosition(idx[k],(x/100,y/100,0))
m=rw.GetMol();m.AddConformer(conf)
for a,b in [('Ca','Cm'),('Cb','Cr')]:
    bd=m.GetBondBetweenAtoms(idx[a],idx[b])
    if bd.GetBeginAtomIdx()!=idx[a]: print('flip')
    bd.SetBondDir(Chem.BondDir.BEGINWEDGE)
# replace placeholders: O -> attach Ti; E -> ester; simpler: make smiles with full
Chem.AssignChiralTypesFromBondDirs(m);Chem.AssignStereochemistry(m,force=True,cleanIt=True)
s=Chem.MolToSmiles(m);print(s)
